from pathlib import Path
import html,re,json,hashlib,markdown
P=Path(__file__).resolve().parent
conversation=(P/'CONVERSATION.md').read_text()
text=(P/'GEMINI-TEXT.txt').read_text()
parts=[x for x in text.split('\f') if x.strip()]
assert len(parts)==15
pages=''.join('<section class="pdf-page"><p class="eyebrow">PDF page '+str(n)+'</p><pre>'+html.escape(t)+'</pre></section>' for n,t in enumerate(parts,1))
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#111c24;color:#f1eadc;font:20px/1.8 Georgia,serif;overflow-wrap:anywhere}header,main,footer{max-width:880px;margin:auto;padding:30px 26px}a{color:#a3dfd2}h1{font-weight:normal;font-size:clamp(42px,7vw,70px);line-height:1.12;color:#f4cf8f}h2{color:#edbf85}h3{font:600 18px system-ui}strong{color:#a3dfd2}.eyebrow,aside,figcaption,footer{font:14px/1.75 system-ui}.eyebrow{color:#dfbf88;letter-spacing:1px;text-transform:uppercase}aside{padding:20px;background:#20303a;border-left:3px solid #d3ab71;margin:25px 0}.exchange{padding:15px 22px;border:1px solid #526063;border-radius:7px}.pdf-page{border-top:1px solid #526063;padding:25px 0}pre{font:16px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere}nav{display:flex;flex-wrap:wrap;gap:20px;font:15px system-ui}.stage{font-style:italic;color:#bec8c7}@media print{body{background:white;color:black}h1,h2,h3,strong,a,.eyebrow{color:black}header nav,aside{display:none}.pdf-page{break-before:page}}'''
body=markdown.markdown(conversation,extensions=['extra'])
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Six Authors in Search of an Ending — Manny Glover</title><meta name="description" content="The unedited Six Authors conversation and complete supplied Gemini collaboration, An Unproduceable Closeted Drama, with the original 15-page PDF."><style>'+css+'</style></head><body><header><nav><a href="../">HRL Portfolio</a><a href="../house-of-returning-authors/#gemini-drama">Read inside the megaplay</a></nav><p class="eyebrow">Manny Glover · Michael Emanuel Glover · 29 October 2026</p><h1>Six Authors in Search of an Ending</h1><p>A conversation preserved as written, together with the supplied Gemini-created play.</p><nav><a href="#conversation">The conversation</a><a href="#gemini">The Gemini play</a><a href="CONVERSATION.md">Conversation text</a><a href="Unproduceable_Closeted_Drama_HRL_Portfolio.pdf">Original PDF</a></nav></header><main><aside>Fiction and philosophical theatre. The messages below are unchanged; speaker headings identify the exchange. The supplied PDF is published unchanged and credited as Manny’s collaboration with Gemini, retaining its original byline. Its provocative dialogue, theological cosmology, and mathematical language are dramatic material, not independently verified factual claims.</aside><article id="conversation" class="exchange">'+body+'</article><article id="gemini"><h2>An Unproduceable Closeted Drama!</h2><p>Original byline: <strong>By Emanuel &amp; Manny</strong>. Created with Gemini, as identified by the author.</p><p><a href="Unproduceable_Closeted_Drama_HRL_Portfolio.pdf">Open / download the complete original PDF</a> · <a href="GEMINI-TEXT.txt">Plain-text extraction</a></p><aside>Complete supplied document: 15 pages. The program note describes Acts I–IV; the actual scripts supplied begin at Act V and continue through Act VII. Text below is extracted in page order, with no dialogue rewritten. The PDF governs typography and any extraction discrepancies.</aside>'+pages+'</article></main><footer>Manny Glover with Gemini and ChatGPT / Codex. <a href="README.md">Publication and credit notes</a>. <a href="../house-of-returning-authors/">Return to The House of Returning Authors</a>.</footer></body></html>'
(P/'index.html').write_text(page)
(P/'SOURCE-HASHES.json').write_text(json.dumps({n:hashlib.sha256((P/n).read_bytes()).hexdigest() for n in ['CONVERSATION.md','Unproduceable_Closeted_Drama_HRL_Portfolio.pdf','GEMINI-TEXT.txt']},indent=2)+'\n')
print('Built standalone conversation and all 15 Gemini pages.')
